-- Cache public result-check access codes for fast exact lookup.
-- Codes are still generated by the application from the student UUID, so this
-- table improves lookup speed without changing the printed RC-XXXXXXXX format.

create table if not exists public.result_access_codes (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.portal_users(id) on delete cascade,
  school_id uuid null references public.schools(id) on delete set null,
  access_code text not null,
  code_source text not null default 'fnv1a_uuid_v1',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint result_access_codes_student_unique unique (student_id),
  constraint result_access_codes_access_code_unique unique (access_code),
  constraint result_access_codes_format check (access_code ~ '^RC-[A-Z0-9]{8}$')
);

create index if not exists idx_result_access_codes_school_id
  on public.result_access_codes(school_id);

create index if not exists idx_result_access_codes_updated_at
  on public.result_access_codes(updated_at desc);

alter table public.result_access_codes enable row level security;

drop policy if exists "service role manages result access codes" on public.result_access_codes;
create policy "service role manages result access codes"
  on public.result_access_codes
  for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

grant all on table public.result_access_codes to service_role;
